<?php require_once '../config/database.php';require_once '../includes/auth.php';require_once '../includes/ui.php';requireAdmin();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['claim_id']??0);$action=$_POST['action']??'';$note=trim($_POST['admin_note']??'');if($id&&in_array($action,['APPROVE','REJECT'])){$conn->begin_transaction();try{$st=$conn->prepare("SELECT c.*,f.status found_status,l.status lost_status,f.user_id finder_id FROM claims c JOIN reports f ON f.id=c.report_id JOIN reports l ON l.id=c.lost_report_id WHERE c.id=? FOR UPDATE");$st->bind_param('i',$id);$st->execute();$c=$st->get_result()->fetch_assoc();$st->close();if(!$c)throw new Exception('Klaim tidak ditemukan.');if($c['finder_status']!=='APPROVED' && $c['status']!=='FINDER_APPROVED')throw new Exception('Klaim masih menunggu persetujuan akun penemu.');if($c['status']!=='FINDER_APPROVED'){ $sync='FINDER_APPROVED'; $st=$conn->prepare('UPDATE claims SET status=? WHERE id=?'); $st->bind_param('si',$sync,$id); $st->execute(); $st->close(); }if($action==='APPROVE'){if($c['found_status']!=='VERIFIED'||$c['lost_status']!=='VERIFIED')throw new Exception('Kedua laporan harus masih VERIFIED.');$status='APPROVED';$st=$conn->prepare("UPDATE claims SET status=?,admin_note=?,admin_approved_at=NOW() WHERE id=?");$st->bind_param('ssi',$status,$note,$id);$st->execute();$st->close();$found='CLAIMED';$lost='RETURNED';$st=$conn->prepare('UPDATE reports SET status=? WHERE id=?');$st->bind_param('si',$found,$c['report_id']);$st->execute();$st->close();$st=$conn->prepare('UPDATE reports SET status=? WHERE id=?');$st->bind_param('si',$lost,$c['lost_report_id']);$st->execute();$st->close();$rejected='REJECTED';$st=$conn->prepare("UPDATE claims SET status=?,admin_note=? WHERE report_id=? AND id<>? AND status IN ('PENDING','FINDER_APPROVED')");$st->bind_param('ssii',$rejected,$note,$c['report_id'],$id);$st->execute();$st->close();$msg='Klaim disetujui. Kedua laporan telah diselesaikan.';}else{$status='ADMIN_REJECTED';$st=$conn->prepare('UPDATE claims SET status=?,admin_note=? WHERE id=?');$st->bind_param('ssi',$status,$note,$id);$st->execute();$st->close();$msg='Klaim ditolak admin.';}$conn->commit();}catch(Exception $e){$conn->rollback();$err=$e->getMessage();}}}
$rows=$conn->query("SELECT c.*,f.item_name found_name,f.status found_status,fu.name finder_name,fu.email finder_email,fu.student_status finder_status_profile,fu.semester finder_semester,fu.fakultas finder_fakultas,fu.nomor_hp finder_hp,l.item_name lost_name,l.status lost_status,lu.name claimant,lu.email claimant_email,lu.student_status claimant_status,lu.semester claimant_semester,lu.fakultas claimant_fakultas,lu.nomor_hp claimant_hp,m.score,m.matching_reason FROM claims c JOIN reports f ON f.id=c.report_id JOIN users fu ON fu.id=f.user_id JOIN reports l ON l.id=c.lost_report_id JOIN users lu ON lu.id=c.user_id LEFT JOIN matches m ON m.lost_report_id=c.lost_report_id AND m.found_report_id=c.report_id ORDER BY FIELD(c.status,'FINDER_APPROVED','PENDING','APPROVED','FINDER_REJECTED','ADMIN_REJECTED'),c.created_at DESC");$titleForTop='Verifikasi Klaim';renderHead('Verifikasi Klaim');renderAdminNav('claims');?><div class="content animate-in"><div class="section-head"><div><h1 class="hero-title">Verifikasi Klaim</h1><p class="muted">Finalisasi hanya dilakukan setelah akun penemu menyetujui klaim.</p></div></div><?php if($msg): ?><div class="notice notice-ok"><?= e($msg) ?></div><?php endif; ?><?php if($err): ?><div class="notice notice-error"><?= e($err) ?></div><?php endif; ?><div class="claim-list stagger"><?php if($rows->num_rows): while($c=$rows->fetch_assoc()): ?><div class="card claim-card"><span class="pill <?= $c['status']==='APPROVED'?'pill-green':($c['status']==='ADMIN_REJECTED'?'pill-red':'pill-yellow') ?>"><?= e(statusLabel($c['status'])) ?></span><h2><?= e($c['found_name']) ?></h2><div class="notice notice-info"><b>Hasil Matching:</b> <?= (int)($c['score']??0) ?>% — <?= e($c['matching_reason']??'-') ?></div><div class="grid grid-2"><div><h3>Pelapor Kehilangan</h3><b><?= e($c['claimant']) ?></b><p class="meta"><?= e($c['claimant_email']) ?><br><?= e($c['claimant_status']??'-') ?> · Sem <?= e($c['claimant_semester']??'-') ?><br><?= e($c['claimant_fakultas']??'-') ?><br><?= e($c['claimant_hp']??'-') ?></p></div><div><h3>Penemu</h3><b><?= e($c['finder_name']) ?></b><p class="meta"><?= e($c['finder_email']) ?><br><?= e($c['finder_status_profile']??'-') ?> · Sem <?= e($c['finder_semester']??'-') ?><br><?= e($c['finder_fakultas']??'-') ?><br><?= e($c['finder_hp']??'-') ?></p></div></div><hr><b>Ciri-ciri klaim</b><div class="notice notice-info"><?= nl2br(e($c['item_description'])) ?></div><b>Bukti kepemilikan</b><div class="notice notice-info"><?= nl2br(e($c['evidence'])) ?></div><p class="meta">Penemu: <?= e(statusLabel($c['finder_status'])) ?><?= $c['finder_note']?' — '.e($c['finder_note']):'' ?></p><?php if($c['finder_status']==='APPROVED' && in_array($c['status'],['PENDING','FINDER_APPROVED'],true)): ?><form method="post"><input type="hidden" name="claim_id" value="<?= $c['id'] ?>"><textarea class="form-control" name="admin_note" placeholder="Catatan final admin"></textarea><div class="actions"><button class="btn btn-green" name="action" value="APPROVE">✓ Finalisasi & Selesaikan</button><button class="btn btn-red" data-confirm="Yakin menolak klaim ini?" name="action" value="REJECT">Tolak</button></div></form><?php elseif($c['admin_note']): ?><div class="notice notice-info">Catatan admin: <?= e($c['admin_note']) ?></div><?php endif; ?></div><?php endwhile;else: ?><div class="empty" style="grid-column:1/-1">Belum ada klaim yang masuk.</div><?php endif; ?></div></div><?php renderFooter(); ?>
